import { makeEdgeSeekerFromTable, makeEdgeSeekerIndexedFromTable } from "./makeEdgeSeeker.js";
import { edgeSeekerTables } from "../generated/edge-seeker.js";
import { DISPLAY_P3 } from "../rgb-spaces.js";
import { getRgbConversions } from "../rgb-convert.js";

// Target choice, table lookup and interval-index setup stay outside mapping.
// Both variants share immutable data, but have independent conversion closures
// for different descriptors. The index locates intervals; it never rounds hue.
function create (space, indexed) {
	if (!Object.hasOwn(edgeSeekerTables, space.id)) throw new RangeError(`No Edge Seeker table for ${space.id}`);
	const rows = edgeSeekerTables[space.id];
	const getMaxChroma = indexed ? makeEdgeSeekerIndexedFromTable(rows) : makeEdgeSeekerFromTable(rows);
	const { oklchToClippedRgb, oklchToRgbIfInGamut } = getRgbConversions(space);
	return function map (oklch, out, checkInGamut = false) {
		const l = oklch[0], c = oklch[1], h = oklch[2];
		// Canonical authored-coordinate conversion precedes table lookup and
		// endpoint handling, matching the Rust checked policy.
		if (checkInGamut && oklchToRgbIfInGamut(l, c, h, out)) return out;
		if (l <= 0) {
			out[0] = out[1] = out[2] = 0;
			return out;
		}
		if (l >= 1) {
			out[0] = out[1] = out[2] = 1;
			return out;
		}
		const maxChroma = getMaxChroma(l, h);
		return oklchToClippedRgb(l, c > maxChroma ? maxChroma : c, h, out);
	};
}
export const createEdgeSeeker = space => create(space, false);
export const createEdgeSeekerIndexed = space => create(space, true);
export const edgeSeeker = createEdgeSeeker(DISPLAY_P3);
export const edgeSeekerIndexed = createEdgeSeekerIndexed(DISPLAY_P3);
export function createEdgeSeekerMappers (space) {
	return {
		"edge-seeker": space === DISPLAY_P3 ? edgeSeeker : createEdgeSeeker(space),
		"edge-seeker-indexed": space === DISPLAY_P3 ? edgeSeekerIndexed : createEdgeSeekerIndexed(space),
	};
}

